// Voice Gateway UI - HTTP client for VoiceGatewayApi
import { ERROR_CODES } from './types';
export class VoiceGatewayClient {
    constructor(baseUrl, authToken) {
        this.baseUrl = baseUrl.replace(/\/+$/, '');
        this.authToken = authToken || null;
    }
    close() {
        // No-op for now, can add cleanup logic later
    }
    async request(method, path, body) {
        const url = `${this.baseUrl}${path}`;
        const headers = {
            'Content-Type': 'application/json',
        };
        if (this.authToken) {
            headers['Authorization'] = `Bearer ${this.authToken}`;
        }
        const response = await fetch(url, {
            method,
            headers,
            body: body ? JSON.stringify(body) : undefined,
        });
        if (!response.ok) {
            const error = await response.json().catch(() => ({
                code: ERROR_CODES.SESSION_ERROR,
                message: `HTTP ${response.status}: ${response.statusText}`,
            }));
            throw error;
        }
        return response.json();
    }
    async listConnectors() {
        return this.request('GET', '/api/connectors');
    }
    async listConnections() {
        return this.request('GET', '/api/connections');
    }
    async createConnection(connection) {
        return this.request('POST', '/api/connections', connection);
    }
    async updateConnection(connectionId, updates) {
        return this.request('PATCH', `/api/connections/${connectionId}`, updates);
    }
    async deleteConnection(connectionId) {
        return this.request('DELETE', `/api/connections/${connectionId}`);
    }
    async startVoiceSession(params) {
        return this.request('POST', '/api/sessions', params);
    }
    async endVoiceSession(sessionId) {
        return this.request('DELETE', `/api/sessions/${sessionId}`);
    }
}
